import React from "react";

function App() {

  const bird1 = new Audio(
    "/bird1.mp3"
  );

  const bird2 = new Audio(
    "/bird2.mp3"
  );

  function toggle1() {
    if (bird1.paused) {
      bird1.play();
    } else {
      bird1.pause();
    }
  };

  function toogle2(){
    if(bird2.paused){bird2.play}
    else{bird2.pause}
  }

  return (
    <div>
      <button onClick={toggle1}>Caspian Tern 1</button>
      <button onClick={toogle2}>Caspian Tern 2</button>
    </div>
  );
}

export default App;
